const backLink=document.querySelector(".article__back-link");if(backLink){const e=()=>{history.replaceState({...history.state,hadBack:history.length>1},"")};performance.getEntriesByType("navigation")[0]?.type==="navigate"&&(document.prerendering?document.addEventListener("prerenderingchange",e,{once:!0}):e()),backLink.addEventListener("click",e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;if(history.state?.hadBack===!1)return;history.length>1&&(e.preventDefault(),history.back())})}